@startuml

class Customer {
  + name : string
  + accountDetails : string
}

class Broker {
  + name : string
}

class HeadOffice {}

class Offer {
  + details : string
}

class Contract {
  + signingDate : date
  + billingFrequency : string
}

class InsuranceProduct {
  + price : float
}

class Invoice {
  + amount : float
  + frequency : string
}

class ClaimCase {
  + status : string
}

class Estimator {
  + name : string
  + expertise : string
}

class EstimatorReport {
  + content : string
  + date : date
}

class CompensationDecision {
  + eligibleCosts : float
}

class Claim {
  + description : string
}

class Document {
  + description : string
}

Customer "1" -- "0..*" Contract : signs
Customer "1" -- "0..*" Claim : files
Customer "1" -- "0..*" Invoice : receives
Customer "0..1" -- "1" Broker : is assigned to
Customer "0..*" -- "0..*" InsuranceProduct : interested in

Broker "1" -- "0..*" Customer : manages
HeadOffice -- "0..*" Broker : employs
HeadOffice -- "0..*" Estimator : employs

Contract "1" -- "1" InsuranceProduct : based on
Contract "1" -- "0..*" Invoice : generates
Contract "1" -- "0..*" ClaimCase : results in

ClaimCase "1" -- "1..*" Claim : involves
ClaimCase "1" -- "1..*" EstimatorReport : receives
ClaimCase "0..1" -- "0..1" CompensationDecision : results in
ClaimCase "1" -- "1" Document : requires

Estimator "1" -- "1..*" EstimatorReport : issues
EstimatorReport "1" -- "1" CompensationDecision : informs

CompensationDecision "1" -- "1" Document : relates to

@enduml

